package com.cinemahub.uploader
import android.app.*
import android.content.Intent
import android.net.Uri
import android.os.Build
import android.os.IBinder
import androidx.core.app.NotificationCompat
import org.json.JSONArray
import org.json.JSONObject
import java.net.HttpURLConnection
import java.net.URL
import java.util.Base64
class UploadService:Service(){
 companion object{const val ACTION="UPLOAD";const val CHANNEL="cinemahub_upload";const val NID=701}
 private var active=false
 override fun onBind(i:Intent?):IBinder?=null
 override fun onStartCommand(i:Intent?,flags:Int,startId:Int):Int{channel();startForeground(NID,notice("Preparing upload",0,true));if(i?.action==ACTION&&!active){val token=getSharedPreferences("cinemahub",MODE_PRIVATE).getString("token",null)?:return stop("Sign in again");val a=JSONObject().put("uri",i.getStringExtra("uri")).put("token",token).put("title",i.getStringExtra("title")).put("description",i.getStringExtra("description")).put("kind",i.getStringExtra("kind")).put("subtype",i.getStringExtra("subtype")).put("season",i.getIntExtra("season",1)).put("episode",i.getIntExtra("episode",1)).put("episodeTitle",i.getStringExtra("episodeTitle"));getSharedPreferences("cinemahub_upload",MODE_PRIVATE).edit().putString("pending",a.toString()).apply()};val saved=getSharedPreferences("cinemahub_upload",MODE_PRIVATE).getString("pending",null)?:return stop("No upload queued");if(!active){active=true;Thread{try{upload(JSONObject(saved))}catch(e:Exception){stop("Upload failed: "+e.message)}}.start()};return START_STICKY}
 private fun upload(a:JSONObject){val uri=Uri.parse(a.getString("uri"));val token=a.getString("token");val title=a.getString("title");val size=contentResolver.openAssetFileDescriptor(uri,"r")?.use{it.length}?:-1L;require(size>0){"Unable to read video size"};val name=(uri.lastPathSegment?:"video").replace(Regex("[^A-Za-z0-9._-]"),"_").takeLast(90);val jwt=String(Base64.getUrlDecoder().decode(token.split(".")[1]));val uid=JSONObject(jwt).getString("sub");val path=uid+"/"+System.currentTimeMillis()+"-"+name;val endpoint="https://"+Api.ID+".storage.supabase.co/storage/v1/upload/resumable";val meta=listOf("bucketName" to "cinemahub-videos","objectName" to path,"contentType" to (contentResolver.getType(uri)?:"video/mp4"),"cacheControl" to "3600").joinToString(","){(k,v)->k+" "+Base64.getEncoder().encodeToString(v.toByteArray())};val create=URL(endpoint).openConnection() as HttpURLConnection;create.requestMethod="POST";create.connectTimeout=30000;create.readTimeout=60000;create.setRequestProperty("apikey",Api.KEY);create.setRequestProperty("Authorization","Bearer "+token);create.setRequestProperty("Tus-Resumable","1.0.0");create.setRequestProperty("Upload-Length",size.toString());create.setRequestProperty("Upload-Metadata",meta);val code=create.responseCode;if(code !in 200..299)throw IllegalStateException("Storage setup HTTP "+code+": "+create.errorStream?.bufferedReader()?.readText());val loc=create.getHeaderField("Location")?:error("No upload URL");val target=if(loc.startsWith("http"))loc else endpoint.substringBefore("/storage")+loc;create.disconnect();var offset=0L;val input=contentResolver.openInputStream(uri)?:error("Cannot read video");input.use{stream->val buf=ByteArray(6*1024*1024);while(offset<size){val wanted=minOf(buf.size.toLong(),size-offset).toInt();var got=0;while(got<wanted){val n=stream.read(buf,got,wanted-got);if(n<0)break;got+=n};if(got!=wanted)error("Video file ended early");val c=URL(target).openConnection() as HttpURLConnection;c.requestMethod="PATCH";c.doOutput=true;c.connectTimeout=30000;c.readTimeout=120000;c.setFixedLengthStreamingMode(got);c.setRequestProperty("apikey",Api.KEY);c.setRequestProperty("Authorization","Bearer "+token);c.setRequestProperty("Tus-Resumable","1.0.0");c.setRequestProperty("Upload-Offset",offset.toString());c.setRequestProperty("Content-Type","application/offset+octet-stream");c.outputStream.use{it.write(buf,0,got)};val pc=c.responseCode;if(pc !in 200..299)throw IllegalStateException("Chunk HTTP "+pc+": "+c.errorStream?.bufferedReader()?.readText());offset=c.getHeaderField("Upload-Offset")?.toLongOrNull()?:offset+got;c.disconnect();getSystemService(NotificationManager::class.java).notify(NID,notice("Uploading "+title+" — "+(offset*100/size)+"%",(offset*100/size).toInt(),true))}};save(a,path,token);getSharedPreferences("cinemahub_upload",MODE_PRIVATE).edit().remove("pending").apply();stop("Upload complete: "+title)}
 private fun save(a:JSONObject,path:String,token:String){val kind=a.getString("kind");val title=a.getString("title").replace("\\","\\\\").replace("\"","\\\"");val desc=a.optString("description").replace("\\","\\\\").replace("\"","\\\"");if(kind=="movie"||kind=="content"){val subtype=if(kind=="content")"\""+a.optString("subtype")+"\"" else "null";val body="""[{"kind":"$kind","title":"$title","synopsis":"$desc","movie_video_path":"$path","content_type":$subtype,"is_premium":true,"is_published":false}]""";Api.call("POST","/rest/v1/titles",body,token,mapOf("Prefer" to "return=minimal"))}else{val q="/rest/v1/titles?select=id&kind=eq.series&title=eq."+java.net.URLEncoder.encode(a.getString("title"),"UTF-8")+"&limit=1";val arr=JSONArray(Api.call("GET",q,null,token));val sid=if(arr.length()>0)arr.getJSONObject(0).getString("id")else{val made=JSONArray(Api.call("POST","/rest/v1/titles","""[{"kind":"series","title":"$title","synopsis":"$desc","is_premium":true,"is_published":false}]""",token,mapOf("Prefer" to "return=representation")));made.getJSONObject(0).getString("id")};val sn=a.optInt("season",1);val ss=JSONArray(Api.call("GET","/rest/v1/seasons?select=id&title_id=eq."+sid+"&season_number=eq."+sn+"&limit=1",null,token));val seasonId=if(ss.length()>0)ss.getJSONObject(0).getString("id")else{val made=JSONArray(Api.call("POST","/rest/v1/seasons","""[{"title_id":"$sid","season_number":$sn,"name":"Season $sn","is_published":false}]""",token,mapOf("Prefer" to "return=representation")));made.getJSONObject(0).getString("id")};val ep=a.optString("episodeTitle").ifBlank{"Episode "+a.optInt("episode",1)}.replace("\"","\\\"");Api.call("POST","/rest/v1/episodes","""[{"season_id":"$seasonId","episode_number":${a.optInt("episode",1)},"title":"$ep","synopsis":"$desc","video_path":"$path","is_published":false}]""",token,mapOf("Prefer" to "return=minimal"))}}
 private fun channel(){if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager::class.java).createNotificationChannel(NotificationChannel(CHANNEL,"Video uploads",NotificationManager.IMPORTANCE_LOW))}
 private fun notice(t:String,p:Int,ongoing:Boolean)=NotificationCompat.Builder(this,CHANNEL).setSmallIcon(android.R.drawable.stat_sys_upload).setContentTitle("CinemaHub Uploader").setContentText(t).setProgress(100,p,false).setOngoing(ongoing).setOnlyAlertOnce(true).build()
 private fun stop(msg:String):Int{active=false;getSystemService(NotificationManager::class.java).notify(NID,notice(msg,100,false));stopForeground(STOP_FOREGROUND_DETACH);stopSelf();return START_NOT_STICKY}
}
